import{_ as o,o as t,c as a,a0 as n}from"./chunks/framework.CBux2OW7.js";const h=JSON.parse('{"title":"Atomic UI Components","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/components/atomic-ui.md","filePath":"frontend/components/atomic-ui.md"}'),i={name:"frontend/components/atomic-ui.md"};function r(s,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="atomic-ui-components" tabindex="-1">Atomic UI Components <a class="header-anchor" href="#atomic-ui-components" aria-label="Permalink to &quot;Atomic UI Components&quot;">​</a></h1><p>Located in <code>resources/js/Components/</code>, these are the fundamental building blocks of the TechyNews design system.</p><h2 id="the-primitives" tabindex="-1">The Primitives <a class="header-anchor" href="#the-primitives" aria-label="Permalink to &quot;The Primitives&quot;">​</a></h2><ul><li><code>Button.jsx</code>: A standard HTML <code>&lt;button&gt;</code> wrapper with predefined Tailwind classes (primary, secondary, danger variants).</li><li><code>Input.jsx</code>: A styled text input field.</li><li><code>Label.jsx</code>: Form labels.</li><li><code>Checkbox.jsx</code>: Styled boolean inputs.</li><li><code>Dropdown.jsx</code>: A headless UI or simple state-driven dropdown menu.</li><li><code>Skeleton.jsx</code>: A loading placeholder used during Suspense or async data fetching.</li><li><code>ApplicationLogo.jsx</code>: The SVG or image tag for the brand logo.</li><li><code>ResponsiveNavLink.jsx</code> &amp; <code>NavLink.jsx</code>: Styled Inertia <code>&lt;Link&gt;</code> wrappers for navigation menus.</li><li><code>ValidationErrors.jsx</code>: A component that iterates over Inertia&#39;s <code>errors</code> prop and displays them as red text alerts.</li><li><code>ErrorBoundary.jsx</code>: A React Error Boundary wrapper to catch component crashes gracefully.</li><li><code>AdSlot.jsx</code>: A placeholder or integration component for external ad networks.</li></ul><h2 id="context-for-ai-agents" tabindex="-1">Context for AI Agents <a class="header-anchor" href="#context-for-ai-agents" aria-label="Permalink to &quot;Context for AI Agents&quot;">​</a></h2><p>Agents should <strong>never</strong> write raw HTML <code>&lt;button&gt;</code> or <code>&lt;input&gt;</code> tags when building forms. Always import and use these atomic components to maintain visual consistency across the application.</p>',6)])])}const u=o(i,[["render",r]]);export{h as __pageData,u as default};
